  7	public class MessageService {
  8	    private final List<Message> messages = new ArrayList<>();
  9	    private long nextId = 1;
 10	    private final boolean testMode;
 11	
 12	    public MessageService() {
 13	        this.testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 14	    }
 15	
 16	    public Message sendMessage(String to, String subject, String body) {
 17	        if (!EmailValidator.isValid(to)) {
 18	            Message blocked = new Message(nextId++, MessageChannel.EMAIL, to, subject, body, MessageStatus.BLOCKED);
 19	            messages.add(blocked);
 20	            return blocked;
 21	        }
 22	
 23	        if (testMode) {
 24	            String originalRecipient = to;
 25	            String testBody = "Destinatário original: " + originalRecipient + "\n\n" + body;
 26	            Message testMessage = new Message(
 27	                nextId++,
 28	                MessageChannel.EMAIL,
 29	                "testes@pousadamarealta.com.br",
 30	                "[TESTE] " + subject,
 31	                testBody,
 32	                MessageStatus.SENT
 33	            );
 34	            messages.add(testMessage);
 35	            return testMessage;
 36	        } else {
 37	            Message sent = new Message(nextId++, MessageChannel.EMAIL, to, subject, body, MessageStatus.SENT);
 38	            messages.add(sent);
 39	
 40	            Message archiveCopy = new Message(
 41	                nextId++,
 42	                MessageChannel.EMAIL,
 43	                "arquivo@pousadamarealta.com.br",
 44	                "[Cópia] " + subject,
 45	                body,
 46	                MessageStatus.SENT
 47	            );
 48	            messages.add(archiveCopy);
 49	
 50	            return sent;
 51	        }
 52	    }
 53	
 54	    public List<Message> getAllMessages() {
 55	        return new ArrayList<>(messages);
 56	    }
 57	}
 58	package com.pousadamarealta.service;
 59	
 60	public class EmailValidator {
 61	    public static boolean isValid(String email) {
 62	        if (email == null || email.isEmpty()) {
 63	            return false;
 64	        }
 65	
 66	        int atCount = 0;
 67	        int atIndex = -1;
 68	        for (int i = 0; i < email.length(); i++) {
 69	            if (email.charAt(i) == '@') {
 70	                atCount++;
 71	                atIndex = i;
 72	            }
 73	        }
 74	
 75	        if (atCount != 1) {
 76	            return false;
 77	        }
 78	
 79	        String beforeAt = email.substring(0, atIndex);
 80	        String afterAt = email.substring(atIndex + 1);
 81	
 82	        if (beforeAt.isEmpty()) {
 83	            return false;
 84	        }
 85	
 86	        if (afterAt.isEmpty()) {
 87	            return false;
 88	        }
 89	
 90	        int dotCount = 0;
 91	        for (int i = 0; i < afterAt.length(); i++) {
 92	            if (afterAt.charAt(i) == '.') {
 93	                dotCount++;
 94	            }
 95	        }
 96	
 97	        if (dotCount < 1) {
 98	            return false;
 99	        }
100	
101	        if (afterAt.startsWith(".") || afterAt.endsWith(".")) {
102	            return false;
103	        }
104	
105	        return true;
106	    }
107	}
