170	import com.pousadamarealta.service.*;
171	import io.javalin.Javalin;
172	
173	public class HotelApp {
174	    public static void main(String[] args) {
175	        RoomService roomService = new RoomService();
176	        ReservationService reservationService = new ReservationService(roomService);
177	        MessageService messageService = new MessageService();
178	        ReportService reportService = new ReportService(reservationService, roomService);
179	
180	        RoomController roomController = new RoomController(roomService);
181	        ReservationController reservationController = new ReservationController(
182	            reservationService,
183	            roomService,
184	            messageService
185	        );
186	        MessageController messageController = new MessageController(messageService);
187	        ReportController reportController = new ReportController(reportService);
188	
189	        int port = 7070;
190	        String portEnv = System.getenv("PORT");
191	        if (portEnv != null && !portEnv.isEmpty()) {
192	            try {
193	                port = Integer.parseInt(portEnv);
194	            } catch (NumberFormatException e) {
195	                System.err.println("Invalid PORT environment variable, using default 7070");
196	            }
197	        }
198	
199	        Javalin app = Javalin.create().start(port);
200	
201	        app.get("/rooms", roomController::getRooms);
202	
203	        app.post("/reservations", reservationController::createReservation);
204	        app.get("/reservations/{id}", reservationController::getReservation);
205	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
206	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
207	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
208	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
209	        app.get("/reservations/{id}/document", reservationController::getDocument);
210	
211	        app.get("/messages", messageController::getMessages);
212	
213	        app.get("/reports/occupancy", reportController::getOccupancyReport);
214	        app.get("/reports/revenue", reportController::getRevenueReport);
215	
216	        System.out.println("Hotel system running on port " + port);
217	    }
218	}
