    1	package com.pousadamarealta.controller;
    2	
    3	import com.pousadamarealta.api.*;
    4	import com.pousadamarealta.domain.*;
    5	import com.pousadamarealta.service.*;
    6	import io.javalin.http.Context;
    7	
    8	import java.math.BigDecimal;
    9	import java.time.LocalDate;
   10	import java.time.format.DateTimeFormatter;
   11	
   12	public class ReservationController {
   13	    private final ReservationService reservationService;
   14	    private final RoomService roomService;
   15	    private final MessageService messageService;
   16	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
   17	
   18	    public ReservationController(
   19	        ReservationService reservationService,
   20	        RoomService roomService,
   21	        MessageService messageService
   22	    ) {
   23	        this.reservationService = reservationService;
   24	        this.roomService = roomService;
   25	        this.messageService = messageService;
   26	    }
   27	
   28	    public void createReservation(Context ctx) {
   29	        try {
   30	            CreateReservationRequest body = ctx.bodyAsClass(CreateReservationRequest.class);
   31	
   32	            if (body.roomNumber == 0 || body.guestName == null || body.guestEmail == null ||
   33	                body.guestCpf == null || body.checkIn == null || body.checkOut == null ||
   34	                body.ratePlan == null) {
   35	                ctx.status(400);
   36	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
   37	                return;
   38	            }
   39	
   40	            int roomNumber = body.roomNumber;
   41	            String guestName = body.guestName;
   42	            String guestEmail = body.guestEmail;
   43	            String guestCpf = body.guestCpf;
   44	            String checkInStr = body.checkIn;
   45	            String checkOutStr = body.checkOut;
   46	            int guests = body.guests;
   47	            String ratePlanStr = body.ratePlan;
   48	
   49	            LocalDate checkIn = LocalDate.parse(checkInStr, DATE_FORMATTER);
   50	            LocalDate checkOut = LocalDate.parse(checkOutStr, DATE_FORMATTER);
   51	
   52	            RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
   53	
   54	            Reservation reservation = reservationService.createReservation(
   55	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan
   56	            );
   57	
   58	            ctx.status(201);
   59	            ctx.json(reservationToResponse(reservation));
   60	        } catch (NumberFormatException e) {
   61	            ctx.status(400);
   62	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid number format"));
   63	        } catch (Exception e) {
   64	            handleException(ctx, e);
   65	        }
   66	    }
   67	
   68	    public void getReservation(Context ctx) {
   69	        try {
   70	            long id = Long.parseLong(ctx.pathParam("id"));
   71	            Reservation reservation = reservationService.getReservation(id);
   72	
   73	            if (reservation == null) {
   74	                ctx.status(404);
   75	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   76	                return;
   77	            }
   78	
   79	            ctx.json(reservationToResponse(reservation));
   80	        } catch (Exception e) {
   81	            handleException(ctx, e);
   82	        }
   83	    }
   84	
   85	    public void confirmReservation(Context ctx) {
   86	        try {
   87	            long id = Long.parseLong(ctx.pathParam("id"));
   88	            ConfirmReservationRequest body = ctx.bodyAsClass(ConfirmReservationRequest.class);
   89	
   90	            if (body.amountPaid == null) {
   91	                ctx.status(400);
   92	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing amountPaid field"));
   93	                return;
   94	            }
   95	
   96	            BigDecimal amountPaid = body.amountPaid;
   97	            reservationService.confirmReservation(id, amountPaid);
   98	
   99	            Reservation reservation = reservationService.getReservation(id);
  100	            Room room = roomService.getRoom(reservation.getRoomNumber());
  101	
  102	            String receipt = ReceiptGenerator.generate(reservation, room);
  103	            String emailBody = "Olá, " + reservation.getGuestName() + "!\n\n" +
  104	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
  105	                receipt + "\n" +
  106	                "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
  107	                "Até breve!";
  108	
  109	            messageService.sendMessage(
  110	                reservation.getGuestEmail(),
  111	                "Reserva confirmada - Pousada Maré Alta",
  112	                emailBody
  113	            );
  114	
  115	            ctx.json(reservationToResponse(reservation));
  116	        } catch (Exception e) {
  117	            handleException(ctx, e);
  118	        }
  119	    }
  120	
  121	    public void cancelReservation(Context ctx) {
  122	        try {
  123	            long id = Long.parseLong(ctx.pathParam("id"));
  124	            reservationService.cancelReservation(id);
  125	
  126	            Reservation reservation = reservationService.getReservation(id);
  127	            ctx.json(reservationToResponse(reservation));
  128	        } catch (Exception e) {
  129	            handleException(ctx, e);
  130	        }
  131	    }
  132	
  133	    public void checkIn(Context ctx) {
  134	        try {
  135	            long id = Long.parseLong(ctx.pathParam("id"));
  136	            reservationService.checkIn(id);
  137	
  138	            Reservation reservation = reservationService.getReservation(id);
  139	            ctx.json(reservationToResponse(reservation));
  140	        } catch (Exception e) {
  141	            handleException(ctx, e);
  142	        }
  143	    }
  144	
  145	    public void checkOut(Context ctx) {
  146	        try {
  147	            long id = Long.parseLong(ctx.pathParam("id"));
  148	            reservationService.checkOut(id);
  149	
  150	            Reservation reservation = reservationService.getReservation(id);
  151	            Room room = roomService.getRoom(reservation.getRoomNumber());
  152	
  153	            String receipt = ReceiptGenerator.generate(reservation, room);
  154	            ReceiptResponse receiptResponse = new ReceiptResponse(
  155	                "Comprovante de reserva",
  156	                reservation.getId(),
  157	                reservation.getGuestName(),
  158	                reservation.getGuestCpf(),
  159	                reservation.getRoomNumber(),
  160	                room.getType().getCode(),
  161	                reservation.getCheckIn().toString(),
  162	                reservation.getCheckOut().toString(),
  163	                reservation.getNights(),
  164	                reservation.getSubtotal(),
  165	                reservation.getDiscount(),
  166	                reservation.getTotal()
  167	            );
  168	
  169	            ctx.json(receiptResponse);
  170	        } catch (Exception e) {
  171	            handleException(ctx, e);
  172	        }
  173	    }
  174	
  175	    public void getDocument(Context ctx) {
  176	        try {
  177	            long id = Long.parseLong(ctx.pathParam("id"));
  178	            Reservation reservation = reservationService.getReservation(id);
  179	
  180	            if (reservation == null) {
  181	                ctx.status(404);
  182	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
  183	                return;
  184	            }
  185	
  186	            if (reservation.getStatus() == ReservationStatus.PENDING) {
  187	                ctx.status(409);
  188	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot get document for pending reservation"));
  189	                return;
  190	            }
  191	
  192	            Room room = roomService.getRoom(reservation.getRoomNumber());
  193	
  194	            ReceiptResponse receiptResponse = new ReceiptResponse(
  195	                "Comprovante de reserva",
  196	                reservation.getId(),
  197	                reservation.getGuestName(),
  198	                reservation.getGuestCpf(),
  199	                reservation.getRoomNumber(),
  200	                room.getType().getCode(),
  201	                reservation.getCheckIn().toString(),
  202	                reservation.getCheckOut().toString(),
  203	                reservation.getNights(),
  204	                reservation.getSubtotal(),
  205	                reservation.getDiscount(),
  206	                reservation.getTotal()
  207	            );
  208	
  209	            ctx.json(receiptResponse);
  210	        } catch (Exception e) {
  211	            handleException(ctx, e);
  212	        }
  213	    }
