    69	
    70	public class PriceCalculator {
    71	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
    72	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    73	
    74	    public static class PriceResult {
    75	        public BigDecimal subtotal;
    76	        public BigDecimal discount;
    77	        public BigDecimal total;
    78	
    79	        public PriceResult(BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    80	            this.subtotal = subtotal;
    81	            this.discount = discount;
    82	            this.total = total;
    83	        }
    84	    }
    85	
    86	    private static BigDecimal roundHalfEven(BigDecimal value) {
    87	        return value.setScale(2, RoundingMode.HALF_EVEN);
    88	    }
    89	
    90	    private static boolean isHighSeason(LocalDate date) {
    91	        int month = date.getMonthValue();
    92	        int day = date.getDayOfMonth();
    93	
    94	        if (month == 7) return true;
    95	        if (month == 12 && day >= 15) return true;
    96	        if (month >= 1 && month <= 2) return true;
    97	
    98	        return false;
    99	    }
   100	
   101	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate night) {
   102	        if (isHighSeason(night)) {
   103	            return roundHalfEven(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
   104	        }
   105	        return roundHalfEven(baseRate);
   106	    }
   107	
   108	    public static PriceResult calculate(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut, String ratePlan) {
   109	        long nights = checkOut.toEpochDay() - checkIn.toEpochDay();
   110	
   111	        BigDecimal subtotal = BigDecimal.ZERO;
   112	        LocalDate current = checkIn;
   113	        while (current.isBefore(checkOut)) {
   114	            BigDecimal nightPrice = calculateNightlyPrice(baseRate, current);
   115	            subtotal = subtotal.add(nightPrice);
   116	            current = current.plusDays(1);
   117	        }
   118	        subtotal = roundHalfEven(subtotal);
   119	
   120	        BigDecimal discount = BigDecimal.ZERO;
   121	        if ("NON_REFUNDABLE".equals(ratePlan)) {
   122	            discount = roundHalfEven(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
   123	        }
   124	
   125	        BigDecimal total = roundHalfEven(subtotal.subtract(discount));
   126	
   127	        return new PriceResult(subtotal, discount, total);
   128	    }
   129	}
